function keysetPage(docs, after, limit) {
  const rows = docs
    .filter((d) => after === null || d._id > after)
    .sort((a, b) => a._id - b._id)
    .slice(0, limit);
  const ids = rows.map((d) => d._id);
  return { ids, next: ids[ids.length - 1] };
}

