  let out = [...docs];
  for (const stage of stages) {
    if (stage.$match) out = out.filter((d) => Object.entries(stage.$match).every(([k, v]) => d[k] === v));
    if (stage.$sort) {
      const [field, dir] = Object.entries(stage.$sort)[0];
      out = [...out].sort((a, b) => (a[field] - b[field]) * dir);
    }
    if (stage.$limit !== undefined) out = out.slice(0, stage.$limit);
  }
  return out;
}

