  const byId = new Map(docs.map((d) => [d._id, { ...d }]));
  for (const op of ops) {
    const doc = byId.get(op._id);
    if (doc) Object.assign(doc, op.set);
  }
  return [...byId.values()].sort((a, b) => a._id - b._id);
}

