function toBuckets(readings) {
  const buckets = new Map();
  for (const r of readings) {
    const hour = Math.floor(r.ts / 3600);
    const key = r.sensor;
    const b = buckets.get(key) || { sensor: r.sensor, hour, count: 0, sum: 0 };
    b.count += 1;
    b.sum += r.value;
    buckets.set(key, b);
  }
  return [...buckets.values()].sort((a, b) => a.sensor.localeCompare(b.sensor) || a.hour - b.hour);
}

